var maximumBeauty = function(flowers, newFlowers, target, full, partial) {
    let n = flowers.length;
    // cap at target
    let f = flowers.map(x => Math.min(x, target)).sort((a,b)=>a-b);
    newFlowers = BigInt(newFlowers);
    const T = BigInt(target);
    const FULL = BigInt(full), PARTIAL = BigInt(partial);

    // prefix sums
    let prefix = new Array(n+1);
    prefix[0] = 0n;
    for (let i=0;i<n;i++) prefix[i+1] = prefix[i] + BigInt(f[i]);

    // costToComplete[i] = cost to make gardens from index i..n-1 complete
    // suffix cost: sum(target - f[j]) for j>=i
    // = (n-i)*target - (prefix[n]-prefix[i])
    const costComplete = (i) => T*BigInt(n-i) - (prefix[n]-prefix[i]);

    let ans = 0n;

    // For a prefix of first m gardens (sorted), given budget b, find max possible minimum
    // all gardens in prefix must be < target (to be incomplete). We want minimum level.
    // binary search level L (0 <= L <= target-1), cost to raise all below L to L.
    // We need for each m the best minimum. 

    // Precompute: function given m and budget b returns max min
    const maxMin = (m, b) => {
        if (m === 0) return -1n; // no incomplete gardens
        // we want max L in [0, target-1] such that cost to raise all < L up to L <= b
        // but min can't exceed f values... actually min is the minimum of first m gardens after raising
        // The minimum after optimal fill: we raise lowest ones.
        // binary search L from 0 to target-1
        let lo = 0n, hi = T-1n, best = 0n;
        // find largest index where f[idx] < L using the sorted first m
        while (lo <= hi) {
            let L = (lo+hi)/2n;
            // count gardens in first m with f < L -> cost = count*L - sum of those
            // find upper bound of L-1 i.e. number of elements < L in f[0..m-1]
            let cnt = lowerBound(f, Number(L), m); // number of elements < L
            let cost = L*BigInt(cnt) - prefix[cnt];
            if (cost <= b) { best = L; lo = L+1n; }
            else hi = L-1n;
        }
        return best;
    };

    function lowerBound(arr, val, m) {
        // number of elements in arr[0..m-1] that are < val
        let lo=0, hi=m;
        while(lo<hi){
            let mid=(lo+hi)>>1;
            if(arr[mid] < val) lo=mid+1; else hi=mid;
        }
        return lo;
    }

    // enumerate k = number of complete gardens from the suffix, k from 0 to n
    // but the complete ones must be the largest ones (greedy: cheapest to complete are largest)
    // for k complete, they are indices n-k..n-1
    for (let k = 0; k <= n; k++) {
        let cc = costComplete(n-k);
        if (cc > newFlowers) break; // completing more costs more; largest first are cheapest
        let rem = newFlowers - cc;
        let m = n - k; // incomplete count
        let beauty = FULL * BigInt(k);
        if (m > 0) {
            let mn = maxMin(m, rem);
            if (mn >= 0n) beauty += PARTIAL * mn;
        }
        if (beauty > ans) ans = beauty;
    }

    return Number(ans);
};
```

