```javascript
/**
 * @param {number} n
 * @param {number} firstPlayer
 * @param {number} secondPlayer
 * @return {number[]}
 */
var earliestAndLatest = function(n, firstPlayer, secondPlayer) {
    const memo = new Map();

    // positions l and r (1-indexed) in a row of size m, returns [min, max] rounds
    function solve(m, l, r) {
        // ensure l <= r, and use symmetry l' = m+1-r, r' = m+1-l
        if (l > r) { const t = l; l = r; r = t; }
        // normalize by symmetry
        const sym_l = m + 1 - r, sym_r = m + 1 - l;
        let a = l, b = r;
        if (sym_l < a || (sym_l === a && sym_r < b)) { a = sym_l; b = sym_r; }
        l = a; b_ = b; r = b;

        const key = m + ',' + l + ',' + r;
        if (memo.has(key)) return memo.get(key);

        // if they meet this round
        if (l + r === m + 1) {
            memo.set(key, [1, 1]);
            return [1, 1];
        }

        let minR = Infinity, maxR = -Infinity;
        const half = Math.floor(m / 2);
        const nextSize = Math.floor((m + 1) / 2);

        // enumerate outcomes of pairs (i, m+1-i) for i=1..half
        // determine new positions of our two players after winners re-ranked
        // For each pair, winner is some original index; we need new position = count of winners with original index < this one +1
        // Easier: enumerate which players win; but our two players always win their matches.
        // Positions l and r are fixed survivors. Enumerate winner choices for other pairs.

        // winners: a set of original positions that survive. Then sort and find new index of l and r.
        // Our l and r must win. For a pair involving l or r, the other is eliminated (our player wins).

        // iterate over all pairs
        const pairs = [];
        for (let i = 1; i <= half; i++) {
            const j = m + 1 - i;
            pairs.push([i, j]);
        }

        // recursive enumeration of choices
        function rec(idx, winners) {
            if (idx === pairs.length) {
                // middle player if odd
                if (m % 2 === 1) {
                    const mid = half + 1;
                    winners.push(mid);
                }
                winners.sort((x, y) => x - y);
                const nl = winners.indexOf(l) + 1;
                const nr = winners.indexOf(r) + 1;
                const res = solve(nextSize, nl, nr);
                if (res[0] + 1 < minR) minR = res[0] + 1;
                if (res[1] + 1 > maxR) maxR = res[1] + 1;
                if (m % 2 === 1) winners.pop();
                return;
            }
            const [i, j] = pairs[idx];
            if (i === l || j === l || i === r || j === r) {
                // our player(s) involved; they win
                if (i === l || i === r) winners.push(i);
                else winners.push(j);
                // handle case where both l and r in same pair - but then l+r==m+1 handled earlier
                rec(idx + 1, winners);
                winners.pop();
            } else {
                // either can win
                winners.push(i);
                rec(idx + 1, winners);
                winners.pop();
                winners.push(j);
                rec(idx + 1, winners);
                winners.pop();
            }
        }

        rec(0, []);

        const ans = [minR, maxR];
        memo.set(key, ans);
        return ans;
    }

    return solve(n, firstPlayer, secondPlayer);
};
