var canCross = function(stones) {
    const n = stones.length;
    const pos = new Map();
    for (let i = 0; i < n; i++) pos.set(stones[i], i);
    const dp = Array.from({length: n}, () => new Set());
    dp[0].add(0);
    for (let i = 0; i < n; i++) {
        for (const k of dp[i]) {
            for (let step = k - 1; step <= k + 1; step++) {
                if (step <= 0) continue;
                const next = stones[i] + step;
                if (pos.has(next)) {
                    dp[pos.get(next)].add(step);
                }
            }
        }
    }
    return dp[n - 1].size > 0;
};
