var largestMagicSquare = function(grid) {
    const m = grid.length, n = grid[0].length;
    const rowPre = Array.from({length: m}, () => new Array(n+1).fill(0));
    const colPre = Array.from({length: m+1}, () => new Array(n).fill(0));
    for (let i = 0; i < m; i++)
        for (let j = 0; j < n; j++)
            rowPre[i][j+1] = rowPre[i][j] + grid[i][j];
    for (let j = 0; j < n; j++)
        for (let i = 0; i < m; i++)
            colPre[i+1][j] = colPre[i][j] + grid[i][j];

    const maxK = Math.min(m, n);
    for (let k = maxK; k >= 2; k--) {
        for (let i = 0; i + k <= m; i++) {
            for (let j = 0; j + k <= n; j++) {
                if (check(i, j, k)) return k;
            }
        }
    }
    return 1;

    function check(r, c, k) {
        const target = rowPre[r][c+k] - rowPre[r][c];
        for (let i = r; i < r+k; i++) {
            if (rowPre[i][c+k] - rowPre[i][c] !== target) return false;
        }
        for (let j = c; j < c+k; j++) {
            if (colPre[r+k][j] - colPre[r][j] !== target) return false;
