var maxTotalFruits = function(fruits, startPos, k) {
    const n = fruits.length;
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] + fruits[i][1];

    let ans = 0;
    let left = 0;
    for (let right = 0; right < n; right++) {
        const rightPos = fruits[right][0];
        while (left <= right) {
            const leftPos = fruits[left][0];
            // cost = min of two strategies
            let cost;
            if (rightPos <= startPos) {
                cost = startPos - leftPos;
            } else if (leftPos >= startPos) {
                cost = rightPos - startPos;
            } else {
                const leftDist = startPos - leftPos;
                const rightDist = rightPos - startPos;
                cost = Math.min(leftDist, rightDist) * 2 + Math.max(leftDist, rightDist);
            }
            if (cost > k) {
                left++;
            } else {
                break;
            }
        }
        if (left <= right) {
            ans = Math.max(ans, prefix[right + 1] - prefix[left]);
        }
    }
    return ans;
};
