            b = (b * b) % m;
            e >>= 1n;
        }
        return r;
    };

    invFact[n] = modpow(fact[n], MOD - 2n, MOD);
    for (let i = n; i > 0; i--) invFact[i-1] = (invFact[i] * BigInt(i)) % MOD;

    const comb = (a, b) => {
        if (b < 0 || b > a) return 0n;
        return (fact[a] * invFact[b] % MOD) * invFact[a-b] % MOD;
    };

    const count = (arr) => {
        const m = arr.length;
        if (m <= 2) return 1n;
        const root = arr[0];
