/**
 * @param {number[]} slices
 * @return {number}
 */
var maxSizeSlices = function(slices) {
    const n = slices.length;
    const k = n / 3;

    const solve = (arr) => {
        const m = arr.length;
        // dp[i][j] = max using first i elements picking j non-adjacent
        const dp = Array.from({length: m + 1}, () => new Array(k + 1).fill(0));
        for (let i = 1; i <= m; i++) {
            for (let j = 1; j <= k; j++) {
                const take = (i >= 2 ? dp[i-2][j-1] : 0) + arr[i-1];
                const skip = dp[i-1][j];
                dp[i][j] = Math.max(take, skip);
            }
        }
        return dp[m][k];
    };

    // exclude first element
    const a = slices.slice(1);
    // exclude last element
    const b = slices.slice(0, n - 1);

    return Math.max(solve(a), solve(b));
};
