var friendRequests = function(n, restrictions, requests) {
    const parent = Array.from({length: n}, (_, i) => i);
    const find = x => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };
    const result = [];
    for (const [u, v] of requests) {
        const pu = find(u), pv = find(v);
        if (pu === pv) {
            result.push(true);
