        let ok = true;
        for (const [x, y] of restrictions) {
            const px = find(x), py = find(y);
            if ((px === pu && py === pv) || (px === pv && py === pu)) {
                ok = false;
                break;
            }
        }
        if (ok) {
            parent[pu] = pv;
        }
        result.push(ok);
    }
    return result;
};
