    const parent = new Array(n * n * 4);
    for (let i = 0; i < parent.length; i++) parent[i] = i;

    function find(x) {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    function union(a, b) {
        parent[find(a)] = find(b);
    }

    // cell (r,c) has 4 triangles: 0 top, 1 right, 2 bottom, 3 left
    const idx = (r, c, k) => (r * n + c) * 4 + k;

    for (let r = 0; r < n; r++) {
