var removeInvalidParentheses = function(s) {
    const isValid = (str) => {
        let count = 0;
        for (const c of str) {
            if (c === '(') count++;
            else if (c === ')') {
                count--;
                if (count < 0) return false;
            }
        }
        return count === 0;
    };

    const result = [];
    const visited = new Set();
    let queue = [s];
    visited.add(s);
    let found = false;

    while (queue.length > 0) {
        const next = [];
        for (const cur of queue) {
            if (isValid(cur)) {
                result.push(cur);
                found = true;
            }
        }
        if (found) break;
        for (const cur of queue) {
            for (let i = 0; i < cur.length; i++) {
                if (cur[i] !== '(' && cur[i] !== ')') continue;
                const newStr = cur.slice(0, i) + cur.slice(i + 1);
                if (!visited.has(newStr)) {
                    visited.add(newStr);
                    next.push(newStr);
                }
            }
        }
        queue = next;
    }

    return result.length > 0 ? result : [""];
};
