 * @param {number} k
 * @return {number[]}
 */
var medianSlidingWindow = function(nums, k) {
    const window = [];
    const result = [];

    const bisectLeft = (arr, x) => {
        let lo = 0, hi = arr.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] < x) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    };

    for (let i = 0; i < nums.length; i++) {
        // insert nums[i] in sorted order
        const pos = bisectLeft(window, nums[i]);
        window.splice(pos, 0, nums[i]);

        if (i >= k) {
            // remove nums[i-k]
            const rem = bisectLeft(window, nums[i - k]);
            window.splice(rem, 1);
        }

        if (i >= k - 1) {
            let median;
            if (k % 2 === 1) {
                median = window[(k - 1) >> 1];
            } else {
                median = (window[k / 2 - 1] + window[k / 2]) / 2;
            }
            result.push(median);
        }
    }

    return result;
};
