    for (const w of words) if (w.length > result.length) return false;

    const assigned = {}; // char -> digit
    const used = new Array(10).fill(false);

    // we process columns from rightmost (index 0 from right)
    // words contribute +, result contributes -

    function solve(col, pos, carry) {
