    while (queue.length > 0) {
        const next = [];
        for (const word of queue) {
            if (word === endWord) return level;
            const arr = word.split('');
            for (let i = 0; i < arr.length; i++) {
                const orig = arr[i];
                for (let c = 97; c <= 122; c++) {
                    arr[i] = String.fromCharCode(c);
                    const cand = arr.join('');
                    if (wordSet.has(cand)) {
                        wordSet.delete(cand);
                        next.push(cand);
                    }
                }
                arr[i] = orig;
            }
        }
        queue = next;
        level++;
    }

    return 0;
};
